   440	  if (typeof stdout !== 'string' || stdout.length === 0) return null;
   441	  let last: unknown = null;
   442	  let index = 0;
   443	  const len = stdout.length;
   444	  while (index <= len) {
   445	    let newline = stdout.indexOf('\n', index);
   446	    if (newline === -1) newline = len;
   447	    const line = stdout.slice(index, newline).trim();
   448	    index = newline + 1;
   449	    if (line.length > 0) {
   450	      let parsed: unknown;
   451	      try {
   452	        parsed = JSON.parse(line);
   453	      } catch {
   454	        parsed = undefined;
   455	      }
   456	      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
   457	        const event = parsed as Record<string, unknown>;
   458	        const type = Object.prototype.hasOwnProperty.call(event, 'type') ? event.type : undefined;
   459	        if (type === 'turn.completed') {
   460	          const usage = Object.prototype.hasOwnProperty.call(event, 'usage') ? event.usage : undefined;
   461	          if (typeof usage === 'object' && usage !== null && !Array.isArray(usage)) {
   462	            last = usage;
   463	          }
   464	        }
   465	      }
   466	    }
   467	    if (newline === len) break;
