56:+export type ReviewerExecutionAuthorityClassification =
57:+  | 'managed-cross-provider-receipt'
58:+  | 'native-host-signed-review'
59:+  | 'degraded-single-host-local-only'
60:+  | 'cross-provider-advisory-only';
61:+
62:+export interface ReviewerExecutionAuthority {
63:+  classification: ReviewerExecutionAuthorityClassification;
64:+  directSignedReviewAllowed: boolean;
65:+  managedReceiptRequired: boolean;
66:+  reviewGatePath: 'managed-receipt' | 'direct-signed-review' | 'local-host-verdict-only' | 'none';
67:+}
68:+
69:+/**
70:+ * Keep native-host, managed cross-provider, and explicit degraded assurance
71:+ * semantically disjoint. A managed receipt is the only cross-provider CLI path
72:+ * into REVIEW evidence; degraded single-host evidence remains a local DONE
73:+ * assurance fact and never borrows either reviewer authority path.
74:+ */
75:+export function classifyReviewerExecutionAuthority(args: {
76:+  executionMode: 'native-host' | 'cross-provider-cli';
77:+  assuranceLevel: 'ordinary-review' | 'degraded-single-host';
78:+  hasManagedEvidenceBinding: boolean;
79:+}): ReviewerExecutionAuthority {
80:+  if (args.assuranceLevel === 'degraded-single-host') {
81:+    return {
82:+      classification: 'degraded-single-host-local-only',
83:+      directSignedReviewAllowed: false,
84:+      managedReceiptRequired: false,
85:+      reviewGatePath: 'local-host-verdict-only',
86:+    };
87:+  }
88:+  if (args.executionMode === 'cross-provider-cli') {
89:+    return args.hasManagedEvidenceBinding
90:+      ? {
91:+        classification: 'managed-cross-provider-receipt',
92:+        directSignedReviewAllowed: false,
93:+        managedReceiptRequired: true,
94:+        reviewGatePath: 'managed-receipt',
95:+      }
96:+      : {
97:+        classification: 'cross-provider-advisory-only',
98:+        directSignedReviewAllowed: false,
99:+        managedReceiptRequired: true,
100:+        reviewGatePath: 'none',
101:+      };
102:+  }
103:+  if (args.hasManagedEvidenceBinding) {
104:+    return {
105:+      classification: 'cross-provider-advisory-only',
106:+      directSignedReviewAllowed: false,
107:+      managedReceiptRequired: true,
108:+      reviewGatePath: 'none',
109:+    };
110:+  }
111:+  return {
112:+    classification: 'native-host-signed-review',
113:+    directSignedReviewAllowed: true,
114:+    managedReceiptRequired: false,
115:+    reviewGatePath: 'direct-signed-review',
116:+  };
