119:+export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
120:+  if (run.assembledPrompt) return run.assembledPrompt;
121:+  const body = resolvePromptRoleBody(run.lane, loadConfig(root).promptEnvelope).body;
122:+  if (rawSha256(body) !== run.promptHash) {
123:+    throw new Error('managed reviewer: legacy ReviewRun prompt hash does not match the canonical role body');
124:+  }
125:+  return body;
