173:+export function verifyManagedReviewEvidence(args: {
174:+  root: string;
175:+  storyId: string;
176:+  agent: string;
177:+  reviewRunId: string;
178:+  lane: string;
179:+  binding: ManagedReviewEvidenceBinding;
180:+  expected: ManagedReviewExpectedBinding;
181:+  evidence?: { kind: 'pass'; pass: ReviewPass } | { kind: 'finding'; finding: Finding };
182:+}): ManagedReviewEvidenceVerification {
183:+  let receipt: ManagedHostRunReceipt;
184:+  let proposal: ManagedReviewEvidenceProposal | null;
185:+  let runBinding: ReturnType<typeof readManagedHostRunBinding>;
186:+  try {
187:+    receipt = managedHostRunReceipt(args.root, args.binding.runId);
188:+    proposal = readManagedReviewEvidenceProposal(args.root, args.binding.runId);
189:+    runBinding = readManagedHostRunBinding(args.root, args.binding.runId);
190:+  } catch (error) {
191:+    const diagnostic = failedDiagnostic();
192:+    return { valid: false, reason: diagnostic.reasons.join(','), diagnostic, receipt: null, proposal: null };
193:+  }
194:+  const terminalPath = join(managedHostRunDirectory(args.root, args.binding.runId), 'terminal.json');
195:+  const runDirectory = managedHostRunDirectory(args.root, args.binding.runId);
196:+  const observedTerminalDigest = sha256(readFileSync(terminalPath, 'utf8'));
197:+  const observedProposalDigest = proposal
198:+    ? sha256(readFileSync(join(runDirectory, 'evidence-proposal.json'), 'utf8'))
199:+    : null;
200:+  const proposalArtifacts = readdirSync(runDirectory)
201:+    .filter(name => /^evidence-proposal(?:[.-].*)?\.json$/.test(name));
202:+  const observedSpecDigest = sha256(readFileSync(join(runDirectory, 'spec.json'), 'utf8'));
203:+  const observedEventJournalDigest = existsSync(join(runDirectory, 'events.jsonl'))
204:+    ? sha256(readFileSync(join(runDirectory, 'events.jsonl'), 'utf8'))
205:+    : sha256('');
206:+  const observedResultDigest = existsSync(join(runDirectory, 'result.json'))
207:+    ? sha256(readFileSync(join(runDirectory, 'result.json'), 'utf8'))
208:+    : null;
209:+  const shapeValid = args.binding.schemaVersion === 'lattice.managed_review_evidence_binding.v1'
210:+    && proposal?.schemaVersion === 'lattice.managed_review_evidence_proposal.v1'
211:+    && Number.isFinite(Date.parse(args.binding.importedAt))
212:+    && args.binding.providerHost === args.expected.providerHost
213:+    && args.binding.managedPromptDigest === args.expected.managedPromptDigest;
214:+  const exactEvidenceMatches = (() => {
215:+    if (!args.evidence) return true;
216:+    if (!proposal) return false;
217:+    if (args.evidence.kind === 'pass') {
218:+      if (proposal.conclusion !== 'pass' || args.binding.proposalFindingIndex !== undefined) return false;
219:+      return digestCanonicalJson({
220:+        note: args.evidence.pass.note,
221:+        readManifest: args.evidence.pass.readManifest,
222:+        readLog: args.evidence.pass.readLog,
223:+        readDiagnostics: args.evidence.pass.readDiagnostics,
224:+      }) === digestCanonicalJson({
225:+        note: proposal.note,
226:+        readManifest: proposal.readManifest,
227:+        readLog: proposal.readLog,
228:+        readDiagnostics: proposal.readDiagnostics,
229:+      });
230:+    }
231:+    if (proposal.conclusion !== 'findings') return false;
232:+    const index = args.binding.proposalFindingIndex;
233:+    if (!Number.isInteger(index) || index! < 0) return false;
234:+    const candidate = proposal.findings?.[index!];
235:+    if (!candidate) return false;
236:+    return digestCanonicalJson({
237:+      desc: args.evidence.finding.desc,
238:+      severity: args.evidence.finding.severity,
239:+      category: args.evidence.finding.category,
240:+      evidenceState: args.evidence.finding.evidenceState ?? 'verified',
241:+      uncertaintyReason: args.evidence.finding.uncertaintyReason,
242:+      files: args.evidence.finding.files ?? [],
243:+      status: args.evidence.finding.status,
244:+      readManifest: args.evidence.finding.readManifest,
245:+      readLog: args.evidence.finding.readLog,
246:+      readDiagnostics: args.evidence.finding.readDiagnostics,
247:+    }) === digestCanonicalJson({
248:+      desc: candidate.desc,
249:+      severity: candidate.severity,
250:+      category: candidate.category,
251:+      evidenceState: candidate.evidenceState ?? 'verified',
252:+      uncertaintyReason: candidate.uncertaintyReason,
253:+      files: candidate.files ?? [],
254:+      status: 'open',
255:+      readManifest: proposal.readManifest,
256:+      readLog: proposal.readLog,
257:+      readDiagnostics: proposal.readDiagnostics,
258:+    });
259:+  })();
260:+  const semanticDigestValid = proposal !== null
261:+    && proposalArtifacts.length === 1
262:+    && proposalArtifacts[0] === 'evidence-proposal.json'
263:+    && receipt.evidenceProposalDigest !== null
264:+    && receipt.evidenceProposalDigest === args.binding.proposalDigest
265:+    && observedProposalDigest === receipt.evidenceProposalDigest
266:+    && observedSpecDigest === receipt.specDigest
267:+    && observedEventJournalDigest === receipt.eventJournalDigest
268:+    && observedResultDigest === receipt.resultDigest
269:+    && exactEvidenceMatches;
270:+  const receiptValid = receipt.receiptId === args.binding.receiptId
271:+    && receipt.terminalDigest === args.binding.terminalDigest
272:+    && observedTerminalDigest === args.binding.terminalDigest
273:+    && receipt.state === 'completed'
274:+    && receipt.processCleanup?.reaped === true
275:+    && receipt.processCleanup.residualProcessGroup === false;
276:+  const subjectMatches = proposal !== null
277:+    && proposal.providerAgent === args.binding.providerAgent
278:+    && args.binding.providerAgent === args.agent
279:+    && args.agent === args.lane
280:+    && proposal.lane === args.lane
281:+    && args.binding.lane === args.lane
282:+    && args.binding.reviewRunId === args.reviewRunId
283:+    && proposal.reviewRunId === args.reviewRunId
284:+    && runBinding.profile === 'managed_reviewer'
285:+    && runBinding.host === args.binding.providerHost
286:+    && runBinding.agentType === args.agent
287:+    && runBinding.lane === args.lane
288:+    && runBinding.reviewRunId === args.reviewRunId;
289:+  const reviewTupleMatches = runBinding.reviewBinding !== null
290:+    && runBinding.reviewBinding.headHash === args.expected.headHash
291:+    && runBinding.reviewBinding.materialHash === args.expected.materialHash
292:+    && runBinding.reviewBinding.storyFilesHash === args.expected.storyFilesHash
293:+    && runBinding.reviewBinding.promptHash === args.expected.promptHash
294:+    && runBinding.reviewBinding.envelopeId === args.expected.envelopeId
295:+    && args.binding.headHash === args.expected.headHash
296:+    && args.binding.materialHash === args.expected.materialHash
297:+    && args.binding.storyFilesHash === args.expected.storyFilesHash
298:+    && args.binding.promptHash === args.expected.promptHash
299:+    && args.binding.envelopeId === args.expected.envelopeId
300:+    && runBinding.promptDigest === args.expected.managedPromptDigest;
301:+  const storyMatches = proposal?.storyId === args.storyId
302:+    && runBinding.storyId === args.storyId;
303:+  const diagnostic = buildProofAdmissibilityDiagnostic({
304:+    artifactKind: 'managed-review-evidence',
305:+    artifactId: args.binding.receiptId,
306:+    consumer: 'REVIEW',
307:+    claim: 'review-pass',
308:+    mode: 'enforce',
309:+    enforcedConsumers: ['REVIEW'],
310:+    checks: {
311:+      schemaVersion: args.binding.schemaVersion,
312:+      strictShapeValid: shapeValid,
313:+      semanticDigestValid,
314:+      signatureOrReceiptBindingValid: receiptValid,
315:+      temporalAndMaterialBindingValid: subjectMatches && storyMatches && reviewTupleMatches,
316:+      subjectMatches,
317:+      storyMatches,
318:+      gatePhaseMatches: true,
319:+      producerBoundaryTrusted: receiptValid && subjectMatches && reviewTupleMatches,
320:+    },
321:+  });
322:+  const valid = diagnostic.allowed && !diagnostic.blocking;
323:+  return {
324:+    valid,
325:+    reason: valid ? 'managed_review_evidence_admissible' : diagnostic.reasons.join(','),
326:+    diagnostic,
327:+    receipt,
328:+    proposal,
329:+  };
330:+}
