  1446	export async function getManagedHostRunStatus(args: {
  1447	  root: string;
  1448	  runId: string;
  1449	  afterGeneration?: number;
  1450	  waitMs?: number;
  1451	  /** Internal handler-smoke seam; production omits this and retains the 30s cap. */
  1452	  maxWaitMs?: number;
