  1454	  const paths = pathsFor(args.root, args.runId);
  1455	  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  1456	  const waitMs = Math.min(
  1457	    boundedManagedHostRunStatusWaitMs(args.waitMs),
  1458	    boundedManagedHostRunStatusWaitMs(args.maxWaitMs ?? MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS),
  1459	  );
  1460	  let run = projectionFor(paths);
  1461	  const baseline = typeof args.afterGeneration === 'number' ? args.afterGeneration : run.generation;
  1462	  const deadline = Date.now() + waitMs;
  1463	  while (true) {
  1464	    await reconcileManagedHostRun(paths, Date.now());
  1465	    run = projectionFor(paths);
  1466	    const changed = run.generation !== baseline || run.terminal !== null;
  1467	    if (changed || Date.now() >= deadline || waitMs === 0) {
  1468	      return {
  1469	        schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
  1470	        changed,
  1471	        run,
  1472	        receipt: run.terminal ? managedHostRunReceipt(args.root, args.runId) : null,
  1473	      };
  1474	    }
  1475	    await sleep(Math.min(50, Math.max(1, deadline - Date.now())));
  1476	  }
