    if (typeof value !== 'string' || !/^(?:sha256:)?[a-f0-9]{64}$/.test(value.trim())) {
      throw new Error(`${label}.${field}: must be a sha256 digest when supplied`);
    }
    return value.trim().replace(/^sha256:/, '');
